from solution import fib
import pytest
from hypothesis import given
import hypothesis.strategies as st


def _ref(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b


def test_examples_from_spec():
    assert fib(10) == 55
    assert fib(1) == 1
    assert fib(8) == 21


def test_base_case_zero():
    assert fib(0) == 0


def test_base_case_two():
    assert _ref(2) == 1
    assert fib(2) == 1


def test_known_sequence_prefix():
    expected = [0, 1, 1, 2, 3, 5, 8, 13, 21, 55 - 34, 55, 89, 144]
    # expected[9] = 34, expected[10] = 55
    assert expected[9] == 34
    for n, v in enumerate(expected):
        assert fib(n) == v, f"n={n}"


def test_larger_known_values():
    assert fib(20) == 6765
    assert fib(30) == 832040


@given(st.integers(min_value=0, max_value=30))
def test_equivalence_to_reference_model(n):
    assert fib(n) == _ref(n)


@given(st.integers(min_value=2, max_value=30))
def test_recurrence_relation(n):
    assert fib(n) == fib(n - 1) + fib(n - 2)


@given(st.integers(min_value=0, max_value=30))
def test_returns_nonnegative_int(n):
    v = fib(n)
    assert isinstance(v, int)
    assert not isinstance(v, bool) or True
    assert v >= 0


@given(st.integers(min_value=0, max_value=30))
def test_monotonic_nondecreasing(n):
    assert fib(n + 1) >= fib(n)


@given(st.integers(min_value=2, max_value=30))
def test_strictly_increasing_after_two(n):
    n = max(n, 3)
    assert fib(n) > fib(n - 1)


@given(st.integers(min_value=1, max_value=25))
def test_cassini_identity(n):
    # Cassini: F(n-1)*F(n+1) - F(n)^2 == (-1)^n
    lhs = fib(n - 1) * fib(n + 1) - fib(n) * fib(n)
    assert lhs == (-1) ** n


@given(st.integers(min_value=0, max_value=25))
def test_sum_identity(n):
    # sum_{i=0..n} F(i) == F(n+2) - 1
    s = sum(fib(i) for i in range(n + 1))
    assert s == fib(n + 2) - 1


@given(st.integers(min_value=0, max_value=50))
def test_deterministic_repeat_call(n):
    assert fib(n) == fib(n)
